{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'payload' not in case:
        raise ValueError('case missing payload')
    payload = case['payload']
    if 'threshold' not in payload:
        raise ValueError('payload missing threshold')
    if 'calls' not in payload:
        raise ValueError('payload missing calls')
    threshold = payload['threshold']
    calls = payload['calls']
    if not isinstance(threshold, (int, float)):
        raise ValueError('threshold must be numeric')
    if not isinstance(calls, list):
        raise ValueError('calls must be a list')
    accepted = []
    diagnostics = []
    for call in calls:
        call_id = call.get('call_id')
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if None in (call_id, loss_without, loss_with, tokens, parseable):
            raise ValueError(f'call {call_id} missing required fields')
        gain = loss_without - loss_with
        if tokens <= 0:
            raise ValueError(f'prediction_tokens must be positive, got {tokens}')
        normalized_gain = gain / tokens
        gain_rounded = round(gain, 8)
        normalized_gain_rounded = round(normalized_gain, 8)
        accepted_flag = bool(parseable) and normalized_gain_rounded >= threshold
        if accepted_flag:
            accepted.append(call_id)
        diag = {
            'call_id': call_id,
            'loss_without_call': loss_without,
            'loss_with_call': loss_with,
            'gain': gain_rounded,
            'normalized_gain': normalized_gain_rounded,
            'parseable': parseable,
            'accepted': accepted_flag
        }
        diagnostics.append(diag)
    return {
        'accepted_call_ids': accepted,
        'diagnostics': diagnostics
    }
"}
